const it = $json;
const waPayload = {
  messaging_product: 'whatsapp',
  to: it.phone,
  type: 'template',
  template: {
    name: '__WA_TEMPLATE_REMINDER__',
    language: { code: '__WA_TEMPLATE_LANG__' },
    components: [
      { type: 'body', parameters: [
        { type: 'text', text: it.client_name || 'Hola' },
        { type: 'text', text: it.cuando },
        { type: 'text', text: it.professional_name }
      ] },
      { type: 'button', sub_type: 'quick_reply', index: '0', parameters: [{ type: 'payload', payload: 'CONFIRMAR_' + it.appointment_id }] },
      { type: 'button', sub_type: 'quick_reply', index: '1', parameters: [{ type: 'payload', payload: 'REPROGRAMAR_' + it.appointment_id }] },
      { type: 'button', sub_type: 'quick_reply', index: '2', parameters: [{ type: 'payload', payload: 'CANCELAR_' + it.appointment_id }] }
    ]
  }
};
return [{ json: { waPayload, appointment_id: it.appointment_id } }];

